v = max(v, vec3(1.0e-10));
v = (log2(v) - AGX_MIN_EV) / (AGX_MAX_EV - AGX_MIN_EV);
v = clamp(v, 0.0, 1.0);
v = agxContrast(v);
v = AGX_OUTSET * v;
v = pow(max(v, vec3(0.0)), vec3(2.2));
v = REC2020_TO_SRGB * v;
